import"./chunk-VC46IEJQ.js";var a={en:"Arms not confirmed by the authors of this atlas (not recorded here).",zh:"\u672C\u56FE\u96C6\u4F5C\u8005\u672A\u80FD\u6838\u5B9E\u5176\u7EB9\u7AE0\uFF08\u6B64\u5904\u4E0D\u5F55\uFF09\u3002"},n=["#8a8a8a","#3a3a3a"],r=(o,s,t,i={})=>({id:o,name:{en:s,zh:t},...i}),e=(o,s)=>({en:o,zh:s}),l={group:"iron-westerlands",houses:[{id:"greyjoy",names:e("House Greyjoy","\u845B\u96F7\u4E54\u4F0A\u5BB6\u65CF"),region:"iron-islands",seat:"pyke",tier:"great",liege:null,sigil:e("A golden kraken on a black field","\u9ED1\u5E95\u4E0A\u4E00\u53EA\u91D1\u8272\u6D77\u602A"),colors:["#111111","#c9a227"],words:e("We Do Not Sow","\u5F3A\u53D6\u80DC\u4E8E\u82E6\u8015"),summary:e("Lords Reaper of Pyke and paramount lords of the Iron Islands since the Targaryen conquest, claiming descent from the legendary Grey King. They hold to the Old Way of reaving and the Drowned God. Lord Balon's failed rising against King Robert cost him two sons, and his last son Theon was sent to Winterfell as a ward and hostage.","\u6D3E\u514B\u57CE\u7684\u201C\u6536\u5272\u8005\u201D\uFF0C\u81EA\u5766\u683C\u5229\u5B89\u5F81\u670D\u4EE5\u6765\u7EDF\u9886\u94C1\u7FA4\u5C9B\uFF0C\u81EA\u79F0\u4F20\u8BF4\u4E2D\u7070\u738B\u7684\u540E\u88D4\u3002\u5BB6\u65CF\u606A\u5B88\u52AB\u63A0\u7684\u201C\u53E4\u9053\u201D\uFF0C\u4FE1\u5949\u6DF9\u795E\u3002\u5DF4\u9686\u5927\u4EBA\u8D77\u5175\u53CD\u6297\u52B3\u52C3\u56FD\u738B\u5931\u8D25\uFF0C\u6298\u4E86\u4E24\u4E2A\u513F\u5B50\uFF0C\u5E7C\u5B50\u5E2D\u6069\u4E5F\u88AB\u9001\u5F80\u4E34\u51AC\u57CE\u4F5C\u517B\u5B50\u517C\u4EBA\u8D28\u3002"),refs:["agot","acok","affc","twoiaf"],members:[r("quellon-greyjoy","Quellon Greyjoy","\u594E\u4F26\xB7\u845B\u96F7\u4E54\u4F0A",{note:e("Lord Reaper of Pyke before Balon; married three times and tried to temper the Old Way with mainland customs.","\u5DF4\u9686\u4E4B\u524D\u7684\u6D3E\u514B\u57CE\u9886\u4E3B\uFF0C\u4E09\u5EA6\u5A36\u59BB\uFF0C\u66FE\u8BD5\u56FE\u4EE5\u5927\u9646\u98CE\u4FD7\u7F13\u548C\u201C\u53E4\u9053\u201D\u3002")}),r("harlon-greyjoy","Harlon Greyjoy","\u54C8\u9F99\xB7\u845B\u96F7\u4E54\u4F0A",{father:"quellon-greyjoy",note:e("Quellon's eldest son; died of greyscale, walled up in a tower.","\u594E\u4F26\u7684\u957F\u5B50\uFF0C\u67D3\u4E0A\u7070\u9CDE\u75C5\uFF0C\u88AB\u5173\u5728\u5854\u4E2D\u6B7B\u53BB\u3002")}),r("quenton-greyjoy","Quenton Greyjoy","\u6606\u987F\xB7\u845B\u96F7\u4E54\u4F0A",{father:"quellon-greyjoy",note:e("Died young.","\u5E7C\u5E74\u592D\u6298\u3002")}),r("donel-greyjoy","Donel Greyjoy","\u5510\u7EB3\xB7\u845B\u96F7\u4E54\u4F0A",{father:"quellon-greyjoy",note:e("Died young.","\u5E7C\u5E74\u592D\u6298\u3002")}),r("balon-greyjoy","Balon Greyjoy","\u5DF4\u9686\xB7\u845B\u96F7\u4E54\u4F0A",{father:"quellon-greyjoy",spouses:["alannys-harlaw"],note:e("Lord of the Iron Islands; crowned himself in his first rebellion, nine years before the story begins, and was crushed by Robert.","\u94C1\u7FA4\u5C9B\u4E4B\u4E3B\uFF1B\u6545\u4E8B\u5F00\u59CB\u524D\u4E5D\u5E74\u9996\u6B21\u8D77\u5175\u79F0\u738B\uFF0C\u88AB\u52B3\u52C3\u51FB\u8D25\u3002"),fate:e("Proclaims himself king again in the War of the Five Kings and dies in a fall from a bridge at Pyke during a storm.","\u4E94\u738B\u4E4B\u6218\u4E2D\u518D\u5EA6\u79F0\u738B\uFF0C\u540E\u5728\u98CE\u66B4\u4E2D\u4ECE\u6D3E\u514B\u57CE\u7684\u540A\u6865\u4E0A\u5760\u4EA1\u3002")}),r("euron-greyjoy","Euron Greyjoy","\u6538\u4F26\xB7\u845B\u96F7\u4E54\u4F0A",{father:"quellon-greyjoy",note:e(`"Crow's Eye", captain of the Silence; exiled by Balon and absent from the islands.`,"\u4EBA\u79F0\u201C\u9E26\u773C\u201D\uFF0C\u201C\u5BC2\u9759\u53F7\u201D\u8239\u957F\uFF1B\u906D\u5DF4\u9686\u653E\u9010\uFF0C\u8FDC\u79BB\u7FA4\u5C9B\u3002"),fate:e("Returns after Balon's death and wins the kingsmoot on Old Wyk.","\u5DF4\u9686\u6B7B\u540E\u5F52\u6765\uFF0C\u5728\u8001\u5A01\u514B\u5C9B\u7684\u9009\u738B\u4F1A\u4E0A\u80DC\u51FA\u3002")}),r("victarion-greyjoy","Victarion Greyjoy","\u7EF4\u514B\u5854\u5229\u6602\xB7\u845B\u96F7\u4E54\u4F0A",{father:"quellon-greyjoy",note:e("Lord Captain of the Iron Fleet, a hard and loyal fighter.","\u94C1\u8230\u961F\u53F8\u4EE4\uFF0C\u5F3A\u608D\u800C\u5FE0\u8BDA\u7684\u6218\u58EB\u3002"),fate:e("Loses the kingsmoot to Euron and is sent east toward Meereen.","\u5728\u9009\u738B\u4F1A\u4E0A\u8F93\u7ED9\u6538\u4F26\uFF0C\u88AB\u6D3E\u5F80\u4E1C\u65B9\u7684\u5F25\u6797\u3002")}),r("urrigon-greyjoy","Urrigon Greyjoy","\u4E4C\u91CC\u8D21\xB7\u845B\u96F7\u4E54\u4F0A",{father:"quellon-greyjoy",note:e("Died young of a wound taken in a finger dance.","\u5E74\u5C11\u65F6\u5728\u201C\u6307\u821E\u201D\u4E2D\u53D7\u4F24\u800C\u6B7B\u3002")}),r("aeron-greyjoy","Aeron Greyjoy","\u4F0A\u4F26\xB7\u845B\u96F7\u4E54\u4F0A",{father:"quellon-greyjoy",note:e('"Damphair", once a drunkard, now a priest of the Drowned God.',"\u4EBA\u79F0\u201C\u6E7F\u53D1\u201D\uFF0C\u66FE\u662F\u9152\u5F92\uFF0C\u540E\u6210\u4E3A\u6DF9\u795E\u7684\u796D\u53F8\u3002"),fate:e("Calls the kingsmoot and, after Euron's victory, goes into hiding to rouse the islands against him.","\u53EC\u96C6\u9009\u738B\u4F1A\uFF1B\u6538\u4F26\u80DC\u51FA\u540E\uFF0C\u4ED6\u9690\u533F\u8D77\u6765\uFF0C\u6B32\u53D1\u52A8\u7FA4\u5C9B\u53CD\u5BF9\u6538\u4F26\u3002")}),r("robin-greyjoy","Robin Greyjoy","\u7F57\u5BBE\xB7\u845B\u96F7\u4E54\u4F0A",{father:"quellon-greyjoy",note:e("Quellon's son by his third wife; simple-minded.","\u594E\u4F26\u7B2C\u4E09\u4EFB\u59BB\u5B50\u6240\u751F\uFF0C\u5FC3\u667A\u4E0D\u5168\u3002")}),r("rodrik-greyjoy","Rodrik Greyjoy","\u7F57\u5FB7\u5229\u514B\xB7\u845B\u96F7\u4E54\u4F0A",{father:"balon-greyjoy",mother:"alannys-harlaw",note:e("Balon's eldest son; killed at Seagard during the Greyjoy Rebellion.","\u5DF4\u9686\u7684\u957F\u5B50\uFF0C\u845B\u96F7\u4E54\u4F0A\u53DB\u4E71\u4E2D\u6218\u6B7B\u4E8E\u6D77\u7586\u57CE\u3002")}),r("maron-greyjoy","Maron Greyjoy","\u9A6C\u4F26\xB7\u845B\u96F7\u4E54\u4F0A",{father:"balon-greyjoy",mother:"alannys-harlaw",note:e("Killed at Pyke when the royal army breached the walls.","\u738B\u519B\u653B\u7834\u6D3E\u514B\u57CE\u65F6\u6218\u6B7B\u3002")}),r("asha-greyjoy","Asha Greyjoy","\u963F\u838E\xB7\u845B\u96F7\u4E54\u4F0A",{father:"balon-greyjoy",mother:"alannys-harlaw",note:e("Balon's daughter and captain of the Black Wind, bold and well liked among the ironborn.","\u5DF4\u9686\u4E4B\u5973\uFF0C\u201C\u9ED1\u98CE\u53F7\u201D\u8239\u957F\uFF0C\u52C7\u6562\u800C\u6DF1\u5F97\u94C1\u6C11\u7231\u6234\u3002"),fate:e("Stands at the kingsmoot, loses, and later falls into Stannis's hands in the North.","\u5728\u9009\u738B\u4F1A\u4E0A\u843D\u8D25\uFF0C\u540E\u5728\u5317\u5883\u843D\u5165\u53F2\u5766\u5C3C\u65AF\u624B\u4E2D\u3002")}),r("theon-greyjoy","Theon Greyjoy","\u5E2D\u6069\xB7\u845B\u96F7\u4E54\u4F0A",{father:"balon-greyjoy",mother:"alannys-harlaw",note:e("Balon's last surviving son, raised at Winterfell as Eddard Stark's ward.","\u5DF4\u9686\u4EC5\u5B58\u7684\u513F\u5B50\uFF0C\u5728\u4E34\u51AC\u57CE\u7531\u827E\u5FB7\xB7\u53F2\u5854\u514B\u6536\u4E3A\u517B\u5B50\u3002"),fate:e("Seizes Winterfell for his father, loses it, and is held and broken by Ramsay Bolton.","\u4E3A\u7236\u4EB2\u593A\u53D6\u4E34\u51AC\u57CE\u540E\u53C8\u5931\u5B88\uFF0C\u843D\u5165\u62C9\u59C6\u65AF\xB7\u6CE2\u987F\u4E4B\u624B\uFF0C\u9971\u53D7\u6298\u78E8\u3002")})]},{id:"harlaw",names:e("House Harlaw","\u54C8\u5C14\u6D1B\u5BB6\u65CF"),region:"iron-islands",seat:"ten-towers",otherSeats:["harlaw-hall","grey-garden","tower-of-glimmering","harridan-hill"],tier:"major",liege:"greyjoy",sigil:e("A silver scythe on black","\u9ED1\u5E95\u4E0A\u4E00\u67C4\u94F6\u8272\u957F\u9570"),colors:["#111111","#c0c4c8"],summary:e("The richest and most numerous house of the Iron Islands, ruling Harlaw from Ten Towers through several cadet branches. Lord Rodrik, called the Reader, is famous among the ironborn for his library. His sister Alannys is Lord Balon's wife.","\u94C1\u7FA4\u5C9B\u6700\u5BCC\u6709\u3001\u4EBA\u4E01\u6700\u65FA\u7684\u5BB6\u65CF\uFF0C\u4EE5\u5341\u5854\u57CE\u4E3A\u4E3B\u5821\uFF0C\u53E6\u6709\u6570\u4E2A\u5206\u652F\u6563\u5C45\u54C8\u5C14\u6D1B\u5C9B\u3002\u7F57\u5FB7\u5229\u514B\u5927\u4EBA\u4EBA\u79F0\u201C\u8BFB\u4E66\u4EBA\u201D\uFF0C\u4EE5\u85CF\u4E66\u4E4B\u4E30\u95FB\u540D\u94C1\u6C11\u4E4B\u95F4\u3002\u5176\u59B9\u963F\u62C9\u59AE\u4E1D\u662F\u5DF4\u9686\u5927\u4EBA\u7684\u59BB\u5B50\u3002"),refs:["acok","affc","twoiaf"],members:[r("rodrik-harlaw","Rodrik Harlaw","\u7F57\u5FB7\u5229\u514B\xB7\u54C8\u5C14\u6D1B",{note:e('"The Reader", Lord of Harlaw and Lord of Ten Towers; a bookish but shrewd man whose own children are dead.',"\u4EBA\u79F0\u201C\u8BFB\u4E66\u4EBA\u201D\uFF0C\u54C8\u5C14\u6D1B\u5C9B\u9886\u4E3B\u3001\u5341\u5854\u57CE\u57CE\u4E3B\uFF1B\u55DC\u4E66\u800C\u7CBE\u660E\uFF0C\u5B50\u5973\u5747\u5DF2\u4EA1\u6545\u3002"),fate:e("Backs his niece Asha at the kingsmoot.","\u5728\u9009\u738B\u4F1A\u4E0A\u652F\u6301\u5916\u7525\u5973\u963F\u838E\u3002")}),r("gwynesse-harlaw","Gwynesse Harlaw","\u845B\u6E29\u59AE\u4E1D\xB7\u54C8\u5C14\u6D1B",{note:e("Elder sister of Rodrik; presses her own claim to Ten Towers.","\u7F57\u5FB7\u5229\u514B\u7684\u59D0\u59D0\uFF0C\u575A\u6301\u81EA\u5DF1\u5BF9\u5341\u5854\u57CE\u7684\u7EE7\u627F\u6743\u3002")}),r("alannys-harlaw","Alannys Harlaw","\u963F\u62C9\u59AE\u4E1D\xB7\u54C8\u5C14\u6D1B",{spouses:["balon-greyjoy"],note:e("Wife of Balon Greyjoy; grief for her dead sons has left her frail and confused.","\u5DF4\u9686\xB7\u845B\u96F7\u4E54\u4F0A\u4E4B\u59BB\uFF0C\u56E0\u4E27\u5B50\u4E4B\u75DB\u800C\u4F53\u5F31\u795E\u660F\u3002")}),r("sigfryd-harlaw","Sigfryd Harlaw","\u5E2D\u683C\u5F17\u91CC\u5FB7\xB7\u54C8\u5C14\u6D1B",{note:e('"Silverhair", aged master of Harlaw Hall.',"\u4EBA\u79F0\u201C\u94F6\u53D1\u201D\uFF0C\u54C8\u5C14\u6D1B\u5385\u5E74\u8FC8\u7684\u4E3B\u4EBA\u3002")}),r("hotho-harlaw","Hotho Harlaw","\u970D\u7D22\xB7\u54C8\u5C14\u6D1B",{note:e('"Hotho Humpback", of the Tower of Glimmering.',"\u4EBA\u79F0\u201C\u9A7C\u80CC\u970D\u7D22\u201D\uFF0C\u5FAE\u5149\u5854\u4E4B\u4E3B\u3002")}),r("boremund-harlaw","Boremund Harlaw","\u6CE2\u5C14\u8499\u5FB7\xB7\u54C8\u5C14\u6D1B",{note:e('"Boremund the Blue", of Harridan Hill.',"\u4EBA\u79F0\u201C\u84DD\u8863\u6CE2\u5C14\u8499\u5FB7\u201D\uFF0C\u608D\u5987\u4E18\u4E4B\u4E3B\u3002")}),r("harras-harlaw","Harras Harlaw","\u54C8\u62C9\u65AF\xB7\u54C8\u5C14\u6D1B",{note:e('"The Knight", Ser Harras of Grey Garden, an anointed knight and fierce fighter.',"\u4EBA\u79F0\u201C\u9A91\u58EB\u201D\uFF0C\u7070\u56ED\u7684\u54C8\u62C9\u65AF\u7235\u58EB\uFF0C\u53D7\u8FC7\u6D82\u6CB9\u793C\u7684\u9A91\u58EB\uFF0C\u4F5C\u6218\u51F6\u731B\u3002"),fate:e("Takes service with Euron after the kingsmoot.","\u9009\u738B\u4F1A\u540E\u6295\u6548\u6538\u4F26\u3002")})]},{id:"goodbrother",names:e("House Goodbrother","\u53E4\u67CF\u52D2\u5BB6\u65CF"),region:"iron-islands",seat:"hammerhorn",otherSeats:["shatterstone","downdelving","corpse-lake","crow-spike-keep"],tier:"major",liege:"greyjoy",sigil:a,colors:n,summary:e("The dominant house of Great Wyk, split into several branches whose lords hold Hammerhorn, Shatterstone, Downdelving, Corpse Lake and Crow Spike Keep. Lord Gorold Goodbrother of Hammerhorn heads the senior line.","\u5927\u5A01\u514B\u5C9B\u6700\u5F3A\u5927\u7684\u5BB6\u65CF\uFF0C\u5206\u4E3A\u6570\u652F\uFF0C\u5206\u522B\u636E\u6709\u9524\u89D2\u57CE\u3001\u788E\u77F3\u5821\u3001\u6DF1\u6398\u57CE\u3001\u5C38\u6E56\u4E0E\u9E26\u9489\u5821\u3002\u9524\u89D2\u57CE\u7684\u6208\u7F57\u5FB7\xB7\u53E4\u67CF\u52D2\u5927\u4EBA\u662F\u957F\u623F\u4E4B\u4E3B\u3002"),refs:["affc","twoiaf"]},{id:"drumm",names:e("House Drumm","\u5FB7\u9C81\u59C6\u5BB6\u65CF"),region:"iron-islands",seat:"old-wyk",tier:"minor",liege:"greyjoy",sigil:a,colors:n,summary:e("An old house of Old Wyk. Lord Dunstan Drumm carries Red Rain, a Valyrian steel sword won by an ancestor in a raid, and stands for the old ways at the kingsmoot.","\u8001\u5A01\u514B\u5C9B\u7684\u53E4\u8001\u5BB6\u65CF\u3002\u9093\u65AF\u5766\xB7\u5FB7\u9C81\u59C6\u5927\u4EBA\u4F69\u5E26\u74E6\u96F7\u5229\u4E9A\u94A2\u5251\u201C\u7EA2\u96E8\u201D\uFF0C\u90A3\u662F\u5176\u5148\u7956\u5728\u52AB\u63A0\u4E2D\u6240\u5F97\uFF1B\u4ED6\u5728\u9009\u738B\u4F1A\u4E0A\u4EE5\u53E4\u9053\u4EE3\u8A00\u4EBA\u81EA\u5C45\u3002"),refs:["affc","twoiaf"]},{id:"stonehouse",names:e("House Stonehouse","\u77F3\u5C4B\u5BB6\u65CF"),region:"iron-islands",seat:"old-wyk",tier:"minor",liege:"greyjoy",sigil:a,colors:n,summary:e("A house of Old Wyk, the holy island of the Drowned God, sworn to the Greyjoys.","\u8001\u5A01\u514B\u5C9B\u4E0A\u7684\u5BB6\u65CF\uFF0C\u6548\u5FE0\u845B\u96F7\u4E54\u4F0A\u5BB6\u65CF\uFF1B\u8001\u5A01\u514B\u662F\u6DF9\u795E\u7684\u5723\u5C9B\u3002"),refs:["affc"]},{id:"botley",names:e("House Botley","\u6CE2\u7279\u5229\u5BB6\u65CF"),region:"iron-islands",seat:"lordsport",tier:"minor",liege:"greyjoy",sigil:e("A shoal of silver fish on pale green","\u6DE1\u7EFF\u5E95\u4E0A\u4E00\u7FA4\u94F6\u8272\u5C0F\u9C7C"),colors:["#a9c8a0","#d8dde0"],summary:e("Lords of Lordsport, the harbour town beneath Pyke. Their closeness to the Seastone Chair makes them deeply involved in its quarrels.","\u6D3E\u514B\u57CE\u4E0B\u6E2F\u9547\u9886\u4E3B\u6E2F\u7684\u9886\u4E3B\u3002\u56E0\u79BB\u6D77\u77F3\u4E4B\u4F4D\u8FD1\u5728\u54AB\u5C3A\uFF0C\u5BB6\u65CF\u6DF1\u9677\u5176\u4E2D\u7684\u6743\u4E89\u3002"),refs:["acok","affc"],spoiler:!1},{id:"wynch",names:e("House Wynch","\u6E29\u5947\u5BB6\u65CF"),region:"iron-islands",seat:"iron-holt",tier:"minor",liege:"greyjoy",sigil:e("A bloody moon on purple","\u7D2B\u5E95\u4E0A\u4E00\u8F6E\u8840\u6708"),colors:["#5b2a6e","#b3202a"],summary:e("Lords of Iron Holt on the island of Pyke, one of the Greyjoys' nearest vassals.","\u6D3E\u514B\u5C9B\u4E0A\u94C1\u6797\u57CE\u7684\u9886\u4E3B\uFF0C\u662F\u845B\u96F7\u4E54\u4F0A\u5BB6\u65CF\u6700\u8FD1\u7684\u5C01\u81E3\u4E4B\u4E00\u3002"),refs:["acok","affc"]},{id:"blacktyde",names:e("House Blacktyde","\u5E03\u83B1\u5854\u5BB6\u65CF"),region:"iron-islands",seat:"castle-blacktyde",tier:"minor",liege:"greyjoy",sigil:a,colors:n,summary:e("Lords of the island of Blacktyde. Lord Baelor Blacktyde spent years as a hostage in Oldtown and came home with mainland manners and the Seven, which made him suspect among the ironborn.","\u9ED1\u6F6E\u5C9B\u4E4B\u4E3B\u3002\u5DF4\u57C3\u9686\xB7\u5E03\u83B1\u5854\u5927\u4EBA\u66FE\u5728\u65E7\u9547\u505A\u4E86\u591A\u5E74\u4EBA\u8D28\uFF0C\u5E26\u7740\u5927\u9646\u4E60\u6C14\u4E0E\u4E03\u795E\u4FE1\u4EF0\u5F52\u6765\uFF0C\u56E0\u800C\u5728\u94C1\u6C11\u4E2D\u9971\u53D7\u731C\u7591\u3002"),refs:["affc"]},{id:"saltcliffe",names:e("House Saltcliffe","\u76D0\u5D16\u5BB6\u65CF"),region:"iron-islands",seat:"castle-saltcliffe",tier:"minor",liege:"greyjoy",sigil:a,colors:n,summary:e("Lords of the island of Saltcliffe; Lord Donnor Saltcliffe commands ships in the Greyjoy fleet.","\u76D0\u5D16\u5C9B\u4E4B\u4E3B\uFF1B\u5510\u8BFA\xB7\u76D0\u5D16\u5927\u4EBA\u5728\u845B\u96F7\u4E54\u4F0A\u8230\u961F\u4E2D\u9886\u6709\u8239\u53EA\u3002"),refs:["acok","affc"]},{id:"sunderly",names:e("House Sunderly","\u6851\u5FB7\u5229\u5BB6\u65CF"),region:"iron-islands",seat:"saltcliffe",tier:"minor",liege:"greyjoy",sigil:a,colors:n,summary:e("A house of Saltcliffe. Lord Quellon Greyjoy's second wife, mother of Balon and his full brothers, was a Sunderly.","\u76D0\u5D16\u5C9B\u4E0A\u7684\u5BB6\u65CF\u3002\u594E\u4F26\xB7\u845B\u96F7\u4E54\u4F0A\u5927\u4EBA\u7684\u7B2C\u4E8C\u4EFB\u59BB\u5B50\u2014\u2014\u5DF4\u9686\u53CA\u5176\u540C\u6BCD\u5144\u5F1F\u4E4B\u6BCD\u2014\u2014\u5373\u51FA\u8EAB\u4E8E\u6B64\u3002"),refs:["affc","twoiaf"]},{id:"sparr",names:e("House Sparr","\u65AF\u5DF4\u5C14\u5BB6\u65CF"),region:"iron-islands",seat:"great-wyk",tier:"minor",liege:"greyjoy",sigil:a,colors:n,summary:e("A house of Great Wyk; its lord is among the captains who gather for the kingsmoot.","\u5927\u5A01\u514B\u5C9B\u4E0A\u7684\u5BB6\u65CF\uFF0C\u5176\u9886\u4E3B\u662F\u805A\u96C6\u53C2\u52A0\u9009\u738B\u4F1A\u7684\u8239\u957F\u4E4B\u4E00\u3002"),refs:["acok","affc"]},{id:"merlyn",names:e("House Merlyn","\u6885\u6797\u5BB6\u65CF"),region:"iron-islands",seat:"pebbleton",tier:"minor",liege:"greyjoy",sigil:a,colors:n,summary:e("Lords of Pebbleton on Great Wyk. Lord Meldred Merlyn, old and fat, keeps out of the islands' quarrels when he can.","\u5927\u5A01\u514B\u5C9B\u5375\u77F3\u9547\u7684\u9886\u4E3B\u3002\u6885\u5FB7\u745E\xB7\u6885\u6797\u5927\u4EBA\u5E74\u8001\u4F53\u80D6\uFF0C\u80FD\u7F6E\u8EAB\u7FA4\u5C9B\u7EB7\u4E89\u4E4B\u5916\u4FBF\u5C3D\u91CF\u7F6E\u8EAB\u4E8B\u5916\u3002"),refs:["affc"]},{id:"farwynd",names:e("House Farwynd","\u6CD5\u6E29\u5FB7\u5BB6\u65CF"),region:"iron-islands",seat:"lonely-light",otherSeats:["sealskin-point"],tier:"minor",liege:"greyjoy",sigil:a,colors:n,summary:e("Strange folk of the far west: the Farwynds of the Lonely Light, and a branch at Sealskin Point on Great Wyk. They are whispered to be skinchangers. Lord Gylbert Farwynd dreams of lands beyond the Sunset Sea.","\u8FDC\u5728\u897F\u65B9\u7684\u5947\u7279\u5BB6\u65CF\uFF1A\u4E3B\u652F\u5C45\u4E8E\u5B64\u706F\u5C9B\uFF0C\u53E6\u4E00\u652F\u5728\u5927\u5A01\u514B\u5C9B\u7684\u6D77\u8C79\u76AE\u89D2\u3002\u4F20\u8BF4\u4ED6\u4EEC\u662F\u6613\u5F62\u8005\u3002\u5409\u5C14\u4F2F\u7279\xB7\u6CD5\u6E29\u5FB7\u5927\u4EBA\u68A6\u60F3\u7740\u65E5\u843D\u4E4B\u6D77\u5F7C\u5CB8\u7684\u571F\u5730\u3002"),refs:["affc","twoiaf"]},{id:"orkwood",names:e("House Orkwood","\u6B27\u514B\u4F0D\u5FB7\u5BB6\u65CF"),region:"iron-islands",seat:"orkmont",tier:"minor",liege:"greyjoy",sigil:a,colors:n,summary:e("A house of Orkmont, the island from which Greyjoy kings once ruled before Pyke.","\u5965\u514B\u8499\u5C9B\u4E0A\u7684\u5BB6\u65CF\uFF1B\u5728\u6D3E\u514B\u57CE\u4E4B\u524D\uFF0C\u845B\u96F7\u4E54\u4F0A\u8BF8\u738B\u66FE\u4EE5\u6B64\u5C9B\u4E3A\u636E\u70B9\u3002"),refs:["affc","twoiaf"]},{id:"tawney",names:e("House Tawney","\u5510\u5C3C\u5BB6\u65CF"),region:"iron-islands",seat:"orkmont",tier:"minor",liege:"greyjoy",sigil:a,colors:n,summary:e("A second house of Orkmont, sworn to the Greyjoys.","\u5965\u514B\u8499\u5C9B\u4E0A\u53E6\u4E00\u5BB6\u65CF\uFF0C\u6548\u5FE0\u845B\u96F7\u4E54\u4F0A\u5BB6\u65CF\u3002"),refs:["affc"]},{id:"volmark",names:e("House Volmark","\u6C83\u9A6C\u514B\u5BB6\u65CF"),region:"iron-islands",seat:"harlaw",tier:"minor",liege:"harlaw",sigil:a,colors:n,summary:e("A house of Harlaw sworn to the Harlaws of Ten Towers. Its blood is said to run back to the old kings of House Hoare.","\u54C8\u5C14\u6D1B\u5C9B\u4E0A\u7684\u5BB6\u65CF\uFF0C\u6548\u5FE0\u5341\u5854\u57CE\u7684\u54C8\u5C14\u6D1B\u5BB6\u65CF\u3002\u636E\u8BF4\u5176\u8840\u8109\u53EF\u4E0A\u6EAF\u81F3\u970D\u5C14\u5BB6\u65CF\u7684\u53E4\u4EE3\u8BF8\u738B\u3002"),refs:["affc","twoiaf"]},{id:"kenning-of-harlaw",names:e("House Kenning of Harlaw","\u54C8\u5C14\u6D1B\u7684\u80AF\u5B81\u5BB6\u65CF"),region:"iron-islands",seat:"harlaw",tier:"minor",liege:"harlaw",sigil:e("The Storm God's cloudy hand, grey, hurling lightning","\u98CE\u66B4\u4E4B\u795E\u7070\u8272\u7684\u4E91\u4E4B\u624B\uFF0C\u63B7\u51FA\u95EA\u7535"),colors:["#3a4a5a","#c0c4c8"],summary:e("An ironborn house of Harlaw, sworn to the Harlaws. Not to be confused with the Kennings of Kayce in the westerlands.","\u54C8\u5C14\u6D1B\u5C9B\u4E0A\u7684\u94C1\u6C11\u5BB6\u65CF\uFF0C\u6548\u5FE0\u54C8\u5C14\u6D1B\u5BB6\u65CF\uFF1B\u4E0E\u897F\u5883\u51EF\u65AF\u7684\u80AF\u5B81\u5BB6\u65CF\u4E0D\u662F\u4E00\u5BB6\u3002"),refs:["affc"]},{id:"lannister",names:e("House Lannister","\u5170\u5C3C\u65AF\u7279\u5BB6\u65CF"),region:"westerlands",seat:"casterly-rock",otherSeats:["lannisport"],tier:"great",liege:null,sigil:e("A golden lion rampant on crimson","\u7EA2\u5E95\u4E0A\u4E00\u5934\u8DC3\u7ACB\u7684\u91D1\u72EE"),colors:["#9b1b1e","#e0b23a"],words:e("Hear Me Roar!","\u542C\u6211\u6012\u543C\uFF01"),summary:e("Lords of Casterly Rock and Wardens of the West, once Kings of the Rock, grown immensely rich on the gold of the western hills. Lord Tywin restored the family's power after his father's weakness, crushing the rebellious Reynes and Tarbecks. His daughter Cersei is Queen to King Robert; her twin Jaime is a knight of the Kingsguard.","\u51EF\u5CA9\u57CE\u516C\u7235\u3001\u897F\u5883\u5B88\u62A4\uFF0C\u6614\u65E5\u7684\u51EF\u5CA9\u738B\uFF0C\u9760\u897F\u90E8\u7FA4\u5C71\u7684\u9EC4\u91D1\u5BCC\u7532\u5929\u4E0B\u3002\u6CF0\u6E29\u516C\u7235\u5728\u5176\u7236\u8F6F\u5F31\u65E0\u80FD\u4E4B\u540E\u91CD\u632F\u5BB6\u5A01\uFF0C\u527F\u706D\u4E86\u4F5C\u4E71\u7684\u96F7\u8036\u65AF\u4E0E\u5854\u8D1D\u514B\u4E24\u5BB6\u3002\u4ED6\u7684\u5973\u513F\u745F\u66E6\u662F\u52B3\u52C3\u56FD\u738B\u7684\u738B\u540E\uFF0C\u5176\u5B6A\u751F\u5F1F\u5F1F\u8A79\u59C6\u662F\u5FA1\u6797\u94C1\u536B\u9A91\u58EB\u3002"),refs:["agot","asos","twoiaf"],members:[r("gerold-lannister","Gerold Lannister","\u6770\u6D1B\u5FB7\xB7\u5170\u5C3C\u65AF\u7279",{note:e('"Gerold the Golden", Lord of Casterly Rock two generations before Tywin.',"\u4EBA\u79F0\u201C\u9EC4\u91D1\u6770\u6D1B\u5FB7\u201D\uFF0C\u6CF0\u6E29\u4E4B\u524D\u4E24\u4EE3\u7684\u51EF\u5CA9\u57CE\u516C\u7235\u3002")}),r("tytos-lannister","Tytos Lannister","\u6CF0\u9640\u65AF\xB7\u5170\u5C3C\u65AF\u7279",{father:"gerold-lannister",spouses:["jeyne-marbrand"],note:e("A genial, weak lord whose bannermen mocked and defied him; Tywin spent his youth undoing the damage.","\u548C\u5584\u800C\u8F6F\u5F31\u7684\u516C\u7235\uFF0C\u5C01\u81E3\u4EEC\u5632\u5F04\u3001\u8FDD\u6297\u4ED6\uFF1B\u6CF0\u6E29\u6574\u4E2A\u9752\u5E74\u65F6\u4EE3\u90FD\u5728\u6536\u62FE\u8FD9\u4E00\u6B8B\u5C40\u3002")}),r("jason-lannister","Jason Lannister","\u6770\u68EE\xB7\u5170\u5C3C\u65AF\u7279",{father:"gerold-lannister",spouses:["marla-prester"],note:e("Tytos's brother; father of Joanna and Stafford.","\u6CF0\u9640\u65AF\u4E4B\u5F1F\uFF0C\u4E54\u5B89\u5A1C\u4E0E\u53F2\u5854\u4F5B\u4E4B\u7236\u3002")}),r("tywin-lannister","Tywin Lannister","\u6CF0\u6E29\xB7\u5170\u5C3C\u65AF\u7279",{father:"tytos-lannister",mother:"jeyne-marbrand",spouses:["joanna-lannister"],note:e("Lord of Casterly Rock, Warden of the West, for twenty years Hand of the King to Aerys II.","\u51EF\u5CA9\u57CE\u516C\u7235\u3001\u897F\u5883\u5B88\u62A4\uFF0C\u66FE\u4EFB\u4F0A\u91CC\u65AF\u4E8C\u4E16\u7684\u56FD\u738B\u4E4B\u624B\u4E8C\u5341\u5E74\u3002"),fate:e("Hand again under Joffrey and Tommen; killed by Tyrion in the privy of the Tower of the Hand.","\u5728\u4E54\u4F5B\u91CC\u548C\u6258\u66FC\u6CBB\u4E0B\u518D\u4EFB\u9996\u76F8\uFF1B\u5728\u9996\u76F8\u5854\u7684\u5395\u6240\u4E2D\u88AB\u63D0\u5229\u6602\u6740\u6B7B\u3002")}),r("kevan-lannister","Kevan Lannister","\u51EF\u51AF\xB7\u5170\u5C3C\u65AF\u7279",{father:"tytos-lannister",mother:"jeyne-marbrand",spouses:["dorna-swyft"],note:e("Tywin's steady younger brother and most trusted captain.","\u6CF0\u6E29\u6C89\u7A33\u7684\u5F1F\u5F1F\uFF0C\u4E5F\u662F\u4ED6\u6700\u4FE1\u4EFB\u7684\u90E8\u5C06\u3002"),fate:e("Regent for Tommen; murdered by Varys.","\u4EFB\u6258\u66FC\u7684\u6444\u653F\uFF0C\u88AB\u74E6\u91CC\u65AF\u6240\u6740\u3002")}),r("genna-lannister","Genna Lannister","\u5409\u5A1C\xB7\u5170\u5C3C\u65AF\u7279",{father:"tytos-lannister",mother:"jeyne-marbrand",spouses:["emmon-frey"],note:e("Tywin's sharp-witted sister, married into House Frey.","\u6CF0\u6E29\u7CBE\u660E\u7684\u59B9\u59B9\uFF0C\u5AC1\u5165\u4F5B\u96F7\u5BB6\u65CF\u3002")}),r("tygett-lannister","Tygett Lannister","\u6CF0\u76D6\u7279\xB7\u5170\u5C3C\u65AF\u7279",{father:"tytos-lannister",mother:"jeyne-marbrand",spouses:["darlessa-marbrand"],note:e("A hot-tempered brother who chafed in Tywin's shadow; died of a pox.","\u6027\u60C5\u66B4\u8E81\uFF0C\u4E45\u5C45\u6CF0\u6E29\u9634\u5F71\u4E0B\u800C\u5FC3\u6000\u4E0D\u5E73\uFF1B\u6B7B\u4E8E\u5929\u82B1\u3002")}),r("gerion-lannister","Gerion Lannister","\u845B\u5229\u6069\xB7\u5170\u5C3C\u65AF\u7279",{father:"tytos-lannister",mother:"jeyne-marbrand",note:e("Tyrion's favourite uncle; sailed for Valyria to recover the lost sword Brightroar and never returned.","\u63D0\u5229\u6602\u6700\u559C\u7231\u7684\u53D4\u53D4\uFF1B\u4E3A\u5BFB\u56DE\u5931\u843D\u7684\u7956\u4F20\u5B9D\u5251\u201C\u5149\u4EAE\u4E4B\u543C\u201D\u9A76\u5411\u74E6\u96F7\u5229\u4E9A\uFF0C\u4E00\u53BB\u4E0D\u8FD4\u3002")}),r("stafford-lannister","Stafford Lannister","\u53F2\u5854\u4F5B\xB7\u5170\u5C3C\u65AF\u7279",{father:"jason-lannister",mother:"marla-prester",note:e("Joanna's brother and Tywin's cousin, a dull but well-born commander.","\u4E54\u5B89\u5A1C\u4E4B\u5144\uFF0C\u6CF0\u6E29\u7684\u5802\u5F1F\uFF0C\u8D44\u8D28\u5E73\u5EB8\u5374\u51FA\u8EAB\u9AD8\u8D35\u7684\u6307\u6325\u5B98\u3002"),fate:e("Killed when Robb Stark falls on his host at Oxcross.","\u7F57\u67CF\xB7\u53F2\u5854\u514B\u7A81\u88AD\u725B\u6E21\u8425\u5730\u65F6\u88AB\u6740\u3002")}),r("joanna-lannister","Joanna Lannister","\u4E54\u5B89\u5A1C\xB7\u5170\u5C3C\u65AF\u7279",{father:"jason-lannister",mother:"marla-prester",spouses:["tywin-lannister"],note:e("Wife and cousin of Tywin; died giving birth to Tyrion.","\u6CF0\u6E29\u7684\u59BB\u5B50\u517C\u5802\u59B9\uFF0C\u751F\u63D0\u5229\u6602\u65F6\u96BE\u4EA7\u800C\u6B7B\u3002")}),r("cersei-lannister","Cersei Lannister","\u745F\u66E6\xB7\u5170\u5C3C\u65AF\u7279",{father:"tywin-lannister",mother:"joanna-lannister",spouses:["robert-baratheon"],note:e("Queen to Robert Baratheon; Jaime's twin.","\u52B3\u52C3\xB7\u62DC\u62C9\u5E2D\u6069\u7684\u738B\u540E\uFF0C\u8A79\u59C6\u7684\u5B6A\u751F\u59D0\u59D0\u3002"),fate:e("Queen Regent after Robert's death; later imprisoned by the Faith and made to walk in atonement.","\u52B3\u52C3\u6B7B\u540E\u6210\u4E3A\u6444\u653F\u592A\u540E\uFF1B\u540E\u906D\u6559\u4F1A\u56DA\u7981\uFF0C\u88AB\u8FEB\u8D64\u8EAB\u8D4E\u7F6A\u6E38\u8857\u3002")}),r("jaime-lannister","Jaime Lannister","\u8A79\u59C6\xB7\u5170\u5C3C\u65AF\u7279",{father:"tywin-lannister",mother:"joanna-lannister",note:e("Knight of the Kingsguard, called Kingslayer for killing Aerys II.","\u5FA1\u6797\u94C1\u536B\u9A91\u58EB\uFF0C\u56E0\u523A\u6740\u4F0A\u91CC\u65AF\u4E8C\u4E16\u800C\u88AB\u79F0\u4E3A\u201C\u5F11\u541B\u8005\u201D\u3002"),fate:e("Captured by Robb Stark, loses his sword hand, and becomes Lord Commander of the Kingsguard.","\u88AB\u7F57\u67CF\xB7\u53F2\u5854\u514B\u4FD8\u864F\uFF0C\u5931\u53BB\u6301\u5251\u4E4B\u624B\uFF0C\u540E\u4EFB\u5FA1\u6797\u94C1\u536B\u961F\u957F\u3002")}),r("tyrion-lannister","Tyrion Lannister","\u63D0\u5229\u6602\xB7\u5170\u5C3C\u65AF\u7279",{father:"tywin-lannister",mother:"joanna-lannister",note:e("A dwarf, the clever and much-scorned youngest child of Tywin.","\u4F8F\u5112\uFF0C\u6CF0\u6E29\u6700\u5C0F\u7684\u5B69\u5B50\uFF0C\u806A\u660E\u8FC7\u4EBA\u5374\u5907\u53D7\u8F7B\u89C6\u3002"),fate:e("Acting Hand in King's Landing; wed to Sansa Stark; accused of Joffrey's murder, he kills his father and flees to Essos.","\u5728\u541B\u4E34\u4EE3\u7406\u9996\u76F8\uFF1B\u5A36\u73CA\u838E\xB7\u53F2\u5854\u514B\u4E3A\u59BB\uFF1B\u88AB\u63A7\u6BD2\u6740\u4E54\u4F5B\u91CC\uFF0C\u6740\u7236\u540E\u9003\u5F80\u5384\u7D22\u65AF\u3002")}),r("lancel-lannister","Lancel Lannister","\u84DD\u8D5B\u5C14\xB7\u5170\u5C3C\u65AF\u7279",{father:"kevan-lannister",mother:"dorna-swyft",note:e("Kevan's eldest son, squire to King Robert.","\u51EF\u51AF\u7684\u957F\u5B50\uFF0C\u52B3\u52C3\u56FD\u738B\u7684\u4F8D\u4ECE\u3002"),fate:e("Wounded on the Blackwater; turns to the Faith and joins the Warrior's Sons.","\u9ED1\u6C34\u6CB3\u4E4B\u6218\u4E2D\u53D7\u4F24\uFF1B\u540E\u7688\u4F9D\u6559\u4F1A\uFF0C\u52A0\u5165\u6218\u58EB\u4E4B\u5B50\u3002")}),r("willem-lannister","Willem Lannister","\u5A01\u5EC9\xB7\u5170\u5C3C\u65AF\u7279",{father:"kevan-lannister",mother:"dorna-swyft",note:e("Twin of Martyn; a squire.","\u9A6C\u4E01\u7684\u5B6A\u751F\u5144\u5F1F\uFF0C\u4F8D\u4ECE\u3002"),fate:e("Killed as a captive at Riverrun by Rickard Karstark.","\u5728\u5954\u6D41\u57CE\u4E3A\u4FD8\u65F6\u88AB\u745E\u5361\u5FB7\xB7\u5361\u53F2\u5854\u514B\u6740\u5BB3\u3002")}),r("martyn-lannister","Martyn Lannister","\u9A6C\u4E01\xB7\u5170\u5C3C\u65AF\u7279",{father:"kevan-lannister",mother:"dorna-swyft",note:e("Twin of Willem; a squire.","\u5A01\u5EC9\u7684\u5B6A\u751F\u5144\u5F1F\uFF0C\u4F8D\u4ECE\u3002")}),r("janei-lannister","Janei Lannister","\u8A79\u857E\xB7\u5170\u5C3C\u65AF\u7279",{father:"kevan-lannister",mother:"dorna-swyft",note:e("Kevan's young daughter.","\u51EF\u51AF\u5E74\u5E7C\u7684\u5973\u513F\u3002")}),r("tyrek-lannister","Tyrek Lannister","\u6CF0\u745E\u514B\xB7\u5170\u5C3C\u65AF\u7279",{father:"tygett-lannister",mother:"darlessa-marbrand",note:e("Tygett's son, a squire at court.","\u6CF0\u76D6\u7279\u4E4B\u5B50\uFF0C\u5BAB\u4E2D\u4F8D\u4ECE\u3002"),fate:e("Vanishes during the riot in King's Landing.","\u5728\u541B\u4E34\u66B4\u52A8\u4E2D\u5931\u8E2A\u3002")}),r("daven-lannister","Daven Lannister","\u6234\u6587\xB7\u5170\u5C3C\u65AF\u7279",{father:"stafford-lannister",note:e("Stafford's son, a knight.","\u53F2\u5854\u4F5B\u4E4B\u5B50\uFF0C\u9A91\u58EB\u3002"),fate:e("Becomes Warden of the West in the field after his father's death.","\u7236\u4EB2\u6B7B\u540E\uFF0C\u5728\u6218\u573A\u4E0A\u51FA\u4EFB\u897F\u5883\u5B88\u62A4\u3002")}),r("cerenna-lannister","Cerenna Lannister","\u745F\u857E\u5A1C\xB7\u5170\u5C3C\u65AF\u7279",{father:"stafford-lannister",note:e("Stafford's daughter.","\u53F2\u5854\u4F5B\u4E4B\u5973\u3002")}),r("myrielle-lannister","Myrielle Lannister","\u7C73\u745E\u513F\xB7\u5170\u5C3C\u65AF\u7279",{father:"stafford-lannister",note:e("Stafford's daughter.","\u53F2\u5854\u4F5B\u4E4B\u5973\u3002")}),r("joy-hill","Joy Hill","\u4E54\u4F0A\xB7\u5E0C\u5C14",{father:"gerion-lannister",note:e("Gerion's bastard daughter, raised at Casterly Rock.","\u845B\u5229\u6069\u7684\u79C1\u751F\u5973\uFF0C\u5728\u51EF\u5CA9\u57CE\u957F\u5927\u3002")})]},{id:"clegane",names:e("House Clegane","\u514B\u91CC\u5188\u5BB6\u65CF"),region:"westerlands",seat:"cleganes-keep",tier:"minor",liege:"lannister",sigil:e("Three black dogs on a yellow field","\u9EC4\u5E95\u4E0A\u4E09\u53EA\u9ED1\u72AC"),colors:["#e3b818","#111111"],summary:e("A young landed-knight house: the founder was a kennelman of Casterly Rock who saved Lord Tytos from a lioness and was rewarded with lands. His grandsons are Ser Gregor, the huge and savage 'Mountain That Rides', and Sandor, the scarred 'Hound' who serves Joffrey.","\u4E00\u4E2A\u65B0\u8FD1\u53D7\u5C01\u7684\u9A91\u58EB\u5BB6\u65CF\uFF1A\u5148\u7956\u662F\u51EF\u5CA9\u57CE\u7684\u9A6F\u72AC\u4EBA\uFF0C\u66FE\u4ECE\u6BCD\u72EE\u722A\u4E0B\u6551\u51FA\u6CF0\u9640\u65AF\u516C\u7235\uFF0C\u56E0\u800C\u53D7\u5C01\u571F\u5730\u3002\u4ED6\u7684\u5B59\u5B50\u662F\u8EAB\u8EAF\u5DE8\u5927\u3001\u6B8B\u66B4\u6210\u6027\u7684\u201C\u9B54\u5C71\u201D\u683C\u96F7\u679C\u7235\u58EB\uFF0C\u4EE5\u53CA\u8138\u4E0A\u5E26\u75A4\u3001\u4E3A\u4E54\u4F5B\u91CC\u6548\u529B\u7684\u201C\u730E\u72D7\u201D\u6851\u94CE\u3002"),refs:["agot","twoiaf"],members:[r("clegane-kennelman","Kennelman of Casterly Rock (name not given)","\u51EF\u5CA9\u57CE\u9A6F\u72AC\u4EBA\uFF08\u540D\u5B57\u4E0D\u8BE6\uFF09",{note:e("Saved Tytos Lannister from a lioness and earned the family its lands.","\u4ECE\u6BCD\u72EE\u722A\u4E0B\u6551\u4E0B\u6CF0\u9640\u65AF\xB7\u5170\u5C3C\u65AF\u7279\uFF0C\u4E3A\u5BB6\u65CF\u6323\u5F97\u571F\u5730\u3002")}),r("clegane-father","Father of Gregor and Sandor (name not given)","\u683C\u96F7\u679C\u4E0E\u6851\u94CE\u4E4B\u7236\uFF08\u540D\u5B57\u4E0D\u8BE6\uFF09",{father:"clegane-kennelman",note:e("A landed knight; covered up the burning of Sandor's face by Gregor.","\u6709\u5730\u9A91\u58EB\uFF1B\u66FE\u63A9\u76D6\u683C\u96F7\u679C\u70E7\u4F24\u6851\u94CE\u8138\u7684\u4E8B\u3002")}),r("gregor-clegane","Gregor Clegane","\u683C\u96F7\u679C\xB7\u514B\u91CC\u5188",{father:"clegane-father",note:e('"The Mountain That Rides", a giant knight and Lannister enforcer.',"\u4EBA\u79F0\u201C\u9B54\u5C71\u201D\uFF0C\u8EAB\u5F62\u5DE8\u5927\u7684\u9A91\u58EB\uFF0C\u5170\u5C3C\u65AF\u7279\u5BB6\u7684\u6253\u624B\u3002"),fate:e("Dies of a poisoned wound from Oberyn Martell; Qyburn takes his body.","\u88AB\u5965\u67CF\u4F26\xB7\u9A6C\u6CF0\u5C14\u7684\u6BD2\u77DB\u6240\u4F24\u800C\u6B7B\uFF0C\u5C38\u4F53\u88AB\u79D1\u672C\u5E26\u8D70\u3002")}),r("sandor-clegane","Sandor Clegane","\u6851\u94CE\xB7\u514B\u91CC\u5188",{father:"clegane-father",note:e('"The Hound", sworn shield to Joffrey, his face burned by Gregor in childhood.',"\u4EBA\u79F0\u201C\u730E\u72D7\u201D\uFF0C\u4E54\u4F5B\u91CC\u7684\u8A93\u8A00\u62A4\u536B\uFF1B\u513F\u65F6\u8138\u88AB\u683C\u96F7\u679C\u70E7\u4F24\u3002"),fate:e("Deserts on the Blackwater; left for dead on the Trident, he may live on as a gravedigger on the Quiet Isle.","\u9ED1\u6C34\u6CB3\u4E4B\u6218\u4E2D\u9003\u79BB\uFF1B\u5728\u4E09\u53C9\u621F\u6CB3\u8FB9\u88AB\u5F03\u7F6E\u7B49\u6B7B\uFF0C\u6216\u8BB8\u5728\u5BC2\u9759\u5C9B\u4E0A\u4EE5\u6398\u5893\u4EBA\u7684\u8EAB\u4EFD\u6D3B\u4E86\u4E0B\u6765\u3002")})]},{id:"marbrand",names:e("House Marbrand","\u9A6C\u5C14\u5E03\u5170\u5BB6\u65CF"),region:"westerlands",seat:"ashemark",tier:"major",liege:"lannister",sigil:e("A burning tree, orange on smoke-grey","\u70DF\u7070\u5E95\u4E0A\u4E00\u68F5\u71C3\u70E7\u7684\u6A59\u8272\u6811"),colors:["#6e6e70","#e0732a"],words:e("Burning Bright","\u71C3\u70E7\u660E\u4EAE"),summary:e("Lords of Ashemark and close kin by marriage to the Lannisters. Ser Addam Marbrand, a childhood friend of Jaime, leads the Lannister outriders in the riverlands.","\u7070\u6807\u57CE\u7684\u9886\u4E3B\uFF0C\u4E0E\u5170\u5C3C\u65AF\u7279\u5BB6\u65CF\u7D2F\u4E16\u8054\u59FB\u3002\u4E9A\u5F53\xB7\u9A6C\u5C14\u5E03\u5170\u7235\u58EB\u662F\u8A79\u59C6\u513F\u65F6\u7684\u597D\u53CB\uFF0C\u5728\u6CB3\u95F4\u5730\u7387\u9886\u5170\u5C3C\u65AF\u7279\u519B\u7684\u65A5\u5019\u3002"),refs:["agot","twoiaf"],members:[r("damon-marbrand","Damon Marbrand","\u8FBE\u8499\xB7\u9A6C\u5C14\u5E03\u5170",{note:e("Lord of Ashemark.","\u7070\u6807\u57CE\u9886\u4E3B\u3002")}),r("addam-marbrand","Addam Marbrand","\u4E9A\u5F53\xB7\u9A6C\u5C14\u5E03\u5170",{father:"damon-marbrand",note:e("Heir to Ashemark, a copper-haired knight and capable scout commander.","\u7070\u6807\u57CE\u7EE7\u627F\u4EBA\uFF0C\u94DC\u53D1\u9A91\u58EB\uFF0C\u51FA\u8272\u7684\u65A5\u5019\u6307\u6325\u5B98\u3002")}),r("jeyne-marbrand","Jeyne Marbrand","\u73CD\u59AE\xB7\u9A6C\u5C14\u5E03\u5170",{spouses:["tytos-lannister"],note:e("Wife of Lord Tytos Lannister, mother of Tywin.","\u6CF0\u9640\u65AF\xB7\u5170\u5C3C\u65AF\u7279\u516C\u7235\u4E4B\u59BB\uFF0C\u6CF0\u6E29\u4E4B\u6BCD\u3002")}),r("darlessa-marbrand","Darlessa Marbrand","\u8FBE\u857E\u838E\xB7\u9A6C\u5C14\u5E03\u5170",{spouses:["tygett-lannister"],note:e("Wife of Tygett Lannister, mother of Tyrek.","\u6CF0\u76D6\u7279\xB7\u5170\u5C3C\u65AF\u7279\u4E4B\u59BB\uFF0C\u6CF0\u745E\u514B\u4E4B\u6BCD\u3002")})]},{id:"westerling",names:e("House Westerling","\u7EF4\u65AF\u7279\u6797\u5BB6\u65CF"),region:"westerlands",seat:"the-crag",tier:"minor",liege:"lannister",sigil:e("Six white seashells on sand","\u6C99\u8272\u5E95\u4E0A\u516D\u679A\u767D\u8272\u8D1D\u58F3"),colors:["#d8c39a","#f4f1ea"],words:e("Honor, not Honors","\u8363\u8A89\u800C\u975E\u8363\u8000"),summary:e("An ancient but impoverished house whose mines at the Crag have long since run dry. Lord Gawen is a loyal Lannister bannerman.","\u53E4\u8001\u5374\u5DF2\u6CA1\u843D\u7684\u5BB6\u65CF\uFF0C\u5CED\u5CA9\u57CE\u7684\u77FF\u8109\u65E9\u5DF2\u67AF\u7AED\u3002\u76D6\u6587\u5927\u4EBA\u662F\u5170\u5C3C\u65AF\u7279\u5BB6\u65CF\u5FE0\u5B9E\u7684\u5C01\u81E3\u3002"),refs:["acok","asos","twoiaf"],members:[r("gawen-westerling","Gawen Westerling","\u76D6\u6587\xB7\u7EF4\u65AF\u7279\u6797",{spouses:["sybell-spicer"],note:e("Lord of the Crag.","\u5CED\u5CA9\u57CE\u9886\u4E3B\u3002")}),r("jeyne-westerling","Jeyne Westerling","\u6770\u59AE\xB7\u7EF4\u65AF\u7279\u6797",{father:"gawen-westerling",mother:"sybell-spicer",note:e("Eldest daughter of Lord Gawen.","\u76D6\u6587\u5927\u4EBA\u7684\u957F\u5973\u3002"),fate:e("Nurses the wounded Robb Stark at the Crag and marries him, breaking his pact with the Freys.","\u5728\u5CED\u5CA9\u57CE\u7167\u6599\u8D1F\u4F24\u7684\u7F57\u67CF\xB7\u53F2\u5854\u514B\u5E76\u4E0E\u4E4B\u6210\u5A5A\uFF0C\u81F4\u4F7F\u7F57\u67CF\u80CC\u5F03\u4E86\u4E0E\u4F5B\u96F7\u5BB6\u7684\u5A5A\u7EA6\u3002")}),r("raynald-westerling","Raynald Westerling","\u96F7\u7EB3\u5FB7\xB7\u7EF4\u65AF\u7279\u6797",{father:"gawen-westerling",mother:"sybell-spicer",note:e("Son of Lord Gawen.","\u76D6\u6587\u5927\u4EBA\u4E4B\u5B50\u3002"),fate:e("Killed at the Red Wedding.","\u6B7B\u4E8E\u8840\u8272\u5A5A\u793C\u3002")}),r("rollam-westerling","Rollam Westerling","\u7F57\u5170\xB7\u7EF4\u65AF\u7279\u6797",{father:"gawen-westerling",mother:"sybell-spicer",note:e("Younger son of Lord Gawen.","\u76D6\u6587\u5927\u4EBA\u7684\u5E7C\u5B50\u3002")}),r("eleyna-westerling","Eleyna Westerling","\u827E\u7433\u5A1C\xB7\u7EF4\u65AF\u7279\u6797",{father:"gawen-westerling",mother:"sybell-spicer",note:e("Younger daughter of Lord Gawen.","\u76D6\u6587\u5927\u4EBA\u7684\u5E7C\u5973\u3002")})]},{id:"spicer",names:e("House Spicer","\u65AF\u6D3E\u745F\u5BB6\u65CF"),region:"westerlands",tier:"minor",liege:"westerling",sigil:a,colors:n,summary:e("A merchant family of no ancient name, risen by trade in spices and by marrying Sybell Spicer to Lord Westerling.","\u5E76\u65E0\u53E4\u8001\u95E8\u7B2C\u7684\u5546\u4EBA\u5BB6\u65CF\uFF0C\u9760\u9999\u6599\u8D38\u6613\u8D77\u5BB6\uFF0C\u53C8\u5C06\u5E2D\u8D1D\u513F\xB7\u65AF\u6D3E\u745F\u5AC1\u7ED9\u7EF4\u65AF\u7279\u6797\u5927\u4EBA\u800C\u8DFB\u8EAB\u8D35\u65CF\u3002"),spoiler:!1,refs:["asos"],members:[r("sybell-spicer","Sybell Spicer","\u5E2D\u8D1D\u513F\xB7\u65AF\u6D3E\u745F",{spouses:["gawen-westerling"],note:e("Lady of the Crag, an ambitious wife and mother.","\u5CED\u5CA9\u57CE\u592B\u4EBA\uFF0C\u91CE\u5FC3\u52C3\u52C3\u7684\u59BB\u5B50\u4E0E\u6BCD\u4EB2\u3002"),fate:e("Secretly bargains with Tywin over her daughter's marriage.","\u6697\u4E2D\u4E0E\u6CF0\u6E29\u5C31\u5973\u513F\u7684\u5A5A\u4E8B\u8FBE\u6210\u4EA4\u6613\u3002")}),r("rolph-spicer","Rolph Spicer","\u7F57\u592B\xB7\u65AF\u6D3E\u745F",{note:e("Sybell's brother, castellan of the Crag.","\u5E2D\u8D1D\u513F\u7684\u5F1F\u5F1F\uFF0C\u5CED\u5CA9\u57CE\u4EE3\u7406\u57CE\u4E3B\u3002"),fate:e("Rewarded with Castamere and a lordship by the Lannisters.","\u88AB\u5170\u5C3C\u65AF\u7279\u5BB6\u65CF\u8D50\u4E88\u5361\u65AF\u7279\u6885\u53CA\u9886\u4E3B\u5934\u8854\u3002")})]},{id:"swyft",names:e("House Swyft","\u53F2\u5A01\u4F5B\u5BB6\u65CF"),region:"westerlands",seat:"cornfield",tier:"minor",liege:"lannister",sigil:e("A blue bantam rooster on yellow","\u9EC4\u5E95\u4E0A\u4E00\u53EA\u84DD\u8272\u77EE\u811A\u516C\u9E21"),colors:["#e3c23a","#2a4f9a"],summary:e("Knights of Cornfield, bound to the Lannisters by Dorna Swyft's marriage to Ser Kevan. Her father Ser Harys rises at court on that connection.","\u7389\u7C73\u7530\u7684\u9A91\u58EB\u5BB6\u65CF\uFF0C\u56E0\u591A\u5A1C\xB7\u53F2\u5A01\u4F5B\u5AC1\u7ED9\u51EF\u51AF\u7235\u58EB\u800C\u4E0E\u5170\u5C3C\u65AF\u7279\u5BB6\u65CF\u7ED3\u4EB2\uFF1B\u5176\u7236\u54C8\u745E\u65AF\u7235\u58EB\u501F\u6B64\u5728\u5BAB\u5EF7\u4E2D\u6B65\u6B65\u9AD8\u5347\u3002"),refs:["acok","asos"],members:[r("harys-swyft","Harys Swyft","\u54C8\u745E\u65AF\xB7\u53F2\u5A01\u4F5B",{note:e("Kevan Lannister's good-father, a fawning courtier.","\u51EF\u51AF\xB7\u5170\u5C3C\u65AF\u7279\u7684\u5CB3\u7236\uFF0C\u8C04\u5A9A\u7684\u5EF7\u81E3\u3002"),fate:e("Hand of the King and later master of coin under Cersei.","\u745F\u66E6\u6444\u653F\u65F6\u4EFB\u56FD\u738B\u4E4B\u624B\uFF0C\u540E\u6539\u4EFB\u8D22\u653F\u5927\u81E3\u3002")}),r("dorna-swyft","Dorna Swyft","\u591A\u5A1C\xB7\u53F2\u5A01\u4F5B",{father:"harys-swyft",spouses:["kevan-lannister"],note:e("Wife of Ser Kevan Lannister.","\u51EF\u51AF\xB7\u5170\u5C3C\u65AF\u7279\u7235\u58EB\u4E4B\u59BB\u3002")})]},{id:"prester",names:e("House Prester","\u666E\u745E\u65AF\u7279\u5BB6\u65CF"),region:"westerlands",seat:"feastfires",tier:"minor",liege:"lannister",sigil:a,colors:n,summary:e("Lords of Feastfires on the westerlands coast. Marla Prester married Jason Lannister and was mother of Joanna, Tywin's wife.","\u897F\u5883\u6D77\u5CB8\u5BB4\u706B\u57CE\u7684\u9886\u4E3B\u3002\u739B\u62C9\xB7\u666E\u745E\u65AF\u7279\u5AC1\u7ED9\u6770\u68EE\xB7\u5170\u5C3C\u65AF\u7279\uFF0C\u662F\u6CF0\u6E29\u4E4B\u59BB\u4E54\u5B89\u5A1C\u7684\u6BCD\u4EB2\u3002"),refs:["agot","twoiaf"],members:[r("marla-prester","Marla Prester","\u739B\u62C9\xB7\u666E\u745E\u65AF\u7279",{spouses:["jason-lannister"],note:e("Mother of Joanna and Stafford Lannister.","\u4E54\u5B89\u5A1C\u4E0E\u53F2\u5854\u4F5B\xB7\u5170\u5C3C\u65AF\u7279\u4E4B\u6BCD\u3002")})]},{id:"crakehall",names:e("House Crakehall","\u514B\u96F7\u514B\u8D6B\u5BB6\u65CF"),region:"westerlands",seat:"crakehall",tier:"major",liege:"lannister",sigil:e("A brindled boar on a striped field (tinctures not confirmed)","\u6761\u7EB9\u5E95\u4E0A\u4E00\u5934\u6591\u7EB9\u91CE\u732A\uFF08\u989C\u8272\u672A\u7ECF\u6838\u5B9E\uFF09"),colors:["#7a5a3a","#e9e2d0"],summary:e("Lords of Crakehall, a strong Lannister bannerman house. Lord Roland's kinsman Ser Lyle, the hulking 'Strongboar', fights in the Lannister host.","\u514B\u96F7\u514B\u8D6B\u57CE\u7684\u9886\u4E3B\uFF0C\u5170\u5C3C\u65AF\u7279\u9EBE\u4E0B\u5B9E\u529B\u96C4\u539A\u7684\u5C01\u81E3\u3002\u7F57\u5170\u5927\u4EBA\u7684\u65CF\u4EBA\u3001\u8EAB\u6750\u9B41\u68A7\u7684\u201C\u58EE\u732A\u201D\u83B1\u5C14\u7235\u58EB\u5728\u5170\u5C3C\u65AF\u7279\u5927\u519B\u4E2D\u4F5C\u6218\u3002"),refs:["agot","acok","twoiaf"]},{id:"lefford",names:e("House Lefford","\u96F7\u4F5B\u5FB7\u5BB6\u65CF"),region:"westerlands",seat:"golden-tooth",tier:"major",liege:"lannister",sigil:a,colors:n,summary:e("Keepers of the Golden Tooth, the castle that holds the main pass between the westerlands and the riverlands. Lord Leo Lefford fights in Tywin's host.","\u91D1\u7259\u57CE\u7684\u5B88\u62A4\u8005\uFF0C\u627C\u5B88\u897F\u5883\u4E0E\u6CB3\u95F4\u5730\u4E4B\u95F4\u7684\u4E3B\u8981\u9698\u53E3\u3002\u5229\u5965\xB7\u96F7\u4F5B\u5FB7\u5927\u4EBA\u5728\u6CF0\u6E29\u519B\u4E2D\u4F5C\u6218\u3002"),refs:["agot","twoiaf"]},{id:"brax",names:e("House Brax","\u5E03\u62C9\u514B\u65AF\u5BB6\u65CF"),region:"westerlands",seat:"hornvale",tier:"major",liege:"lannister",sigil:e("A purple unicorn on silver","\u94F6\u5E95\u4E0A\u4E00\u5934\u7D2B\u8272\u72EC\u89D2\u517D"),colors:["#d8dbe0","#6a3a8a"],summary:e("Lords of Hornvale, near the border with the riverlands. Lord Andros Brax and his kin ride with the Lannister host.","\u89D2\u8C37\u7684\u9886\u4E3B\uFF0C\u9886\u5730\u9760\u8FD1\u6CB3\u95F4\u5730\u8FB9\u754C\u3002\u5B89\u5FB7\u7F57\xB7\u5E03\u62C9\u514B\u65AF\u5927\u4EBA\u53CA\u5176\u65CF\u4EBA\u968F\u5170\u5C3C\u65AF\u7279\u5927\u519B\u51FA\u5F81\u3002"),refs:["agot","acok"]},{id:"payne",names:e("House Payne","\u6D3E\u6069\u5BB6\u65CF"),region:"westerlands",tier:"minor",liege:"lannister",sigil:e("Purple and white checks, with gold coins on the purple","\u7D2B\u767D\u683C\u7EB9\uFF0C\u7D2B\u683C\u4E0A\u7F00\u91D1\u5E01"),colors:["#6a3a8a","#f2efe6"],summary:e("A landed-knight house of many poor branches. Ser Ilyn Payne, whose tongue was torn out on Aerys's order, is King's Justice; young Podrick Payne becomes Tyrion's squire.","\u4E00\u4E2A\u652F\u7CFB\u4F17\u591A\u5374\u5927\u591A\u6E05\u8D2B\u7684\u6709\u5730\u9A91\u58EB\u5BB6\u65CF\u3002\u4F0A\u6797\xB7\u6D3E\u6069\u7235\u58EB\u88AB\u4F0A\u91CC\u65AF\u4E0B\u4EE4\u5272\u53BB\u820C\u5934\uFF0C\u73B0\u4EFB\u738B\u5BB6\u6267\u6CD5\u5B98\uFF1B\u5E74\u5C11\u7684\u6CE2\u5FB7\u745E\u514B\xB7\u6D3E\u6069\u6210\u4E86\u63D0\u5229\u6602\u7684\u4F8D\u4ECE\u3002"),refs:["agot","acok"]},{id:"serrett",names:e("House Serrett","\u8D5B\u745E\u7279\u5BB6\u65CF"),region:"westerlands",seat:"silverhill",tier:"minor",liege:"lannister",sigil:e("A peacock in its pride","\u4E00\u53EA\u5F00\u5C4F\u7684\u5B54\u96C0"),colors:["#2a5d6e","#3c9a7a"],summary:e("Lords of Silverhill, a Lannister bannerman house of the westerlands hills.","\u94F6\u5C71\u57CE\u7684\u9886\u4E3B\uFF0C\u897F\u5883\u4E18\u9675\u4E2D\u7684\u5170\u5C3C\u65AF\u7279\u5C01\u81E3\u3002"),refs:["agot","twoiaf"]},{id:"banefort",names:e("House Banefort","\u6591\u6797\u5BB6\u65CF"),region:"westerlands",seat:"banefort",tier:"minor",liege:"lannister",sigil:a,colors:n,summary:e("Lords of the Banefort on the northern coast, the westerlands' first line against ironborn raiders. Lord Quenten Banefort serves in the Lannister host.","\u5317\u90E8\u6D77\u5CB8\u6591\u6797\u5821\u7684\u9886\u4E3B\uFF0C\u662F\u897F\u5883\u62B5\u5FA1\u94C1\u6C11\u52AB\u63A0\u7684\u7B2C\u4E00\u9053\u9632\u7EBF\u3002\u6606\u5EF7\xB7\u6591\u6797\u5927\u4EBA\u5728\u5170\u5C3C\u65AF\u7279\u519B\u4E2D\u6548\u529B\u3002"),refs:["acok","twoiaf"]},{id:"lydden",names:e("House Lydden","\u83B1\u767B\u5BB6\u65CF"),region:"westerlands",seat:"deep-den",tier:"minor",liege:"lannister",sigil:a,colors:n,summary:e("Lords of Deep Den, which watches the goldroad on the eastern edge of the westerlands. Lord Lewys Lydden marches with Tywin.","\u6DF1\u7A74\u57CE\u7684\u9886\u4E3B\uFF0C\u5B88\u671B\u897F\u5883\u4E1C\u7F18\u7684\u9EC4\u91D1\u5927\u9053\u3002\u8DEF\u6613\u65AF\xB7\u83B1\u767B\u5927\u4EBA\u968F\u6CF0\u6E29\u51FA\u5F81\u3002"),refs:["agot","twoiaf"]},{id:"kenning-of-kayce",names:e("House Kenning of Kayce","\u51EF\u65AF\u7684\u80AF\u5B81\u5BB6\u65CF"),region:"westerlands",seat:"kayce",tier:"minor",liege:"lannister",sigil:a,colors:n,summary:e("Lords of Kayce, the coastal town south of Lannisport, sworn to Casterly Rock.","\u5170\u5C3C\u65AF\u6E2F\u4EE5\u5357\u6D77\u6EE8\u57CE\u9547\u51EF\u65AF\u7684\u9886\u4E3B\uFF0C\u6548\u5FE0\u51EF\u5CA9\u57CE\u3002"),refs:["acok","twoiaf"]},{id:"farman",names:e("House Farman","\u6CD5\u66FC\u5BB6\u65CF"),region:"westerlands",seat:"faircastle",tier:"minor",liege:"lannister",sigil:a,colors:n,summary:e("Lords of Faircastle on Fair Isle, guarding the sea approaches to Lannisport.","\u4ED9\u5973\u5C9B\u4E0A\u4ED9\u5973\u57CE\u7684\u9886\u4E3B\uFF0C\u5B88\u536B\u901A\u5F80\u5170\u5C3C\u65AF\u6E2F\u7684\u6D77\u8DEF\u3002"),refs:["affc","twoiaf"]},{id:"sarsfield",names:e("House Sarsfield","\u8428\u65AF\u83F2\u5C14\u5BB6\u65CF"),region:"westerlands",seat:"sarsfield",tier:"minor",liege:"lannister",sigil:a,colors:n,summary:e("Lords of the castle of Sarsfield, a Lannister bannerman house.","\u8428\u65AF\u83F2\u5C14\u57CE\u7684\u9886\u4E3B\uFF0C\u5170\u5C3C\u65AF\u7279\u5BB6\u65CF\u7684\u5C01\u81E3\u3002"),refs:["agot","twoiaf"]},{id:"reyne",names:e("House Reyne","\u96F7\u8036\u65AF\u5BB6\u65CF"),region:"westerlands",seat:"castamere",tier:"extinct",liege:"lannister",sigil:e("A red lion with a forked tail on silver","\u94F6\u5E95\u4E0A\u4E00\u5934\u53CC\u5C3E\u7EA2\u72EE"),colors:["#d8dbe0","#b3202a"],summary:e("Once the richest house of the west after the Lannisters, grown proud on Castamere's gold. When they rose against Casterly Rock in Tytos's day, young Tywin destroyed them root and branch, an end remembered in the song 'The Rains of Castamere'.","\u66FE\u662F\u4EC5\u6B21\u4E8E\u5170\u5C3C\u65AF\u7279\u7684\u897F\u5883\u9996\u5BCC\uFF0C\u51ED\u5361\u65AF\u7279\u6885\u7684\u9EC4\u91D1\u800C\u9A84\u6A2A\u3002\u6CF0\u9640\u65AF\u5728\u4F4D\u65F6\uFF0C\u4ED6\u4EEC\u8D77\u5175\u53CD\u6297\u51EF\u5CA9\u57CE\uFF0C\u5E74\u8F7B\u7684\u6CF0\u6E29\u5C06\u5176\u65A9\u8349\u9664\u6839\uFF1B\u8FD9\u6BB5\u5F80\u4E8B\u88AB\u5531\u6210\u4E86\u300A\u5361\u65AF\u7279\u6885\u7684\u96E8\u5B63\u300B\u3002"),refs:["acok","asos","twoiaf"]},{id:"tarbeck",names:e("House Tarbeck","\u5854\u8D1D\u514B\u5BB6\u65CF"),region:"westerlands",seat:"tarbeck-hall",tier:"extinct",liege:"lannister",sigil:a,colors:n,summary:e("An old house allied to the Reynes by marriage; Tywin wiped it out and pulled down Tarbeck Hall in the same revolt.","\u4E0E\u96F7\u8036\u65AF\u5BB6\u65CF\u8054\u59FB\u7684\u53E4\u8001\u5BB6\u65CF\uFF1B\u5728\u540C\u4E00\u573A\u53DB\u4E71\u4E2D\u88AB\u6CF0\u6E29\u706D\u95E8\uFF0C\u5854\u8D1D\u514B\u5385\u4E5F\u88AB\u5937\u5E73\u3002"),refs:["asos","twoiaf"]}]};export{l as default};
